style.css:
@-moz-document domain("pinterest.com") {
/* ------------------------------------------
       ГОЛУБАЯ ЦВЕТОВАЯ СХЕМА
       ------------------------------------------ */
    :root {
        /* Основной фон — тёмно-синий */
        --color-background-box-light: #0a1a2b;
        --color-background-box-default: #0a1a2b;
        --color-background-secondary-base: #0a1a2b;
        --color-background-tabs-default-base: #0a1a2b;
        --color-background-button-white-default: #0a1a2b;
        --color-background-wash-light: #0a1a2b;
        --color-background-box-secondary: #102a3f;

        /* Текст — светло-голубой */
        --color-text-default: #c8e2ff;
        --color-icon-default: #6db3ff;

        /* Кнопки и акценты — ярко-голубой */
        --color-background-button-white-hover: #1a4a6a;
        --color-background-button-secondary-hover: #1a4a6a;
    }

    /* ------------------------------------------
       ОСНОВНЫЕ ЭЛЕМЕНТЫ
       ------------------------------------------ */
    body {
        background-color: #0a1a2b !important;
        color: #c8e2ff !important;
    }

    /* Контейнеры с белым фоном — заменяем на синий */
    [style*="background: rgb(255, 255, 255)"],
    #searchBoxContainer > div,
    [data-test-id="more-description-container"],
    div[style^="background: linear-gradient"] {
        background: #0a1a2b !important;
    }

    /* ------------------------------------------
       ТЕКСТ И ЗАГОЛОВКИ
       ------------------------------------------ */
    h1, h2, .text-container {
        color: #c8e2ff !important;
    }

    /* Ссылки делаем ярко-голубыми */
    a {
        color: #4da6ff !important;
    }

    /* ------------------------------------------
       КАРТОЧКИ С КВАДРАТНЫМИ УГЛАМИ
       ------------------------------------------ */
    .OVX {
        border-radius: 0px !important;
        background-color: #102a3f !important; /* чуть светлее для карточек */
    }

    .OVX > div > div > div > div > div > div > div > div:nth-child(2) {
        border-radius: 0px 0 0 0px !important;
    }

    /* ------------------------------------------
       НАВИГАЦИЯ
       ------------------------------------------ */
    #VerticalNavContent {
        border: 0 !important;
        background: #0a1a2b !important;
    }

    /* ------------------------------------------
       КНОПКИ В ГОЛУБЫХ ТОНАХ
       ------------------------------------------ */
    button {
        background-color: #1a4a6a !important;
        color: #c8e2ff !important;
        border: 1px solid #4da6ff !important;
    }

    button:hover {
        background-color: #2a6a8a !important;
        border-color: #6db3ff !important;
    }

    /* ------------------------------------------
       ПОЛЯ ВВОДА
       ------------------------------------------ */
    input[type="text"], input[type="search"], textarea {
        background-color: #102a3f !important;
        color: #c8e2ff !important;
        border: 1px solid #1a4a6a !important;
    }

    input:focus, textarea:focus {
        border-color: #4da6ff !important;
        outline: none !important;
    }

    /* ------------------------------------------
       СКРОЛЛБАР (опционально)
       ------------------------------------------ */
    ::-webkit-scrollbar {
        width: 8px;
        background: #0a1a2b;
    }
    ::-webkit-scrollbar-thumb {
        background: #1a4a6a;
        border-radius: 4px;
    }
    ::-webkit-scrollbar-thumb:hover {
        background: #4da6ff;
    }
}
